actions.script:
const alreadyDisabled = ec.artifactExecution.disableAuthz()
try {
    ec.entity.find('moqui.calc.CalcDocumentEdit').condition('definitionId', definitionId).deleteAll()
    ec.entity.find('moqui.calc.CalcDocumentHead').condition('definitionId', definitionId).deleteAll()
} finally {
    if (!alreadyDisabled) ec.artifactExecution.enableAuthz()
}
